settings.custom_css:
selector{max-width:720px}
selector p{margin:0 0 22px}
selector p:first-child strong{display:block;font-family:var(--e-global-typography-bclead-font-family),sans-serif;font-size:var(--e-global-typography-bclead-font-size);line-height:var(--e-global-typography-bclead-line-height);font-weight:500;color:var(--e-global-color-primary)}
selector h2{font-family:var(--e-global-typography-bcds-font-family),serif;font-size:var(--e-global-typography-bcds-font-size);line-height:var(--e-global-typography-bcds-line-height);letter-spacing:var(--e-global-typography-bcds-letter-spacing);font-weight:400;color:var(--e-global-color-primary);margin:56px 0 18px;scroll-margin-top:130px}
selector h3{font-family:var(--e-global-typography-bccard-font-family),serif;font-size:var(--e-global-typography-bccard-font-size);line-height:var(--e-global-typography-bccard-line-height);letter-spacing:var(--e-global-typography-bccard-letter-spacing);font-weight:400;color:var(--e-global-color-primary);margin:36px 0 12px;scroll-margin-top:130px}
selector a{color:var(--e-global-color-primary);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;transition:color .2s ease}
selector a:hover{color:var(--e-global-color-bcmid)}
selector ul,selector ol{margin:0 0 24px;padding-left:22px}
selector li{margin:0 0 8px;padding-left:4px}
selector li::marker{color:var(--e-global-color-bcmid)}
selector blockquote{margin:40px 0;padding:8px 0 8px 28px;border-left:2px solid var(--e-global-color-primary);font-family:var(--e-global-typography-bcds-font-family),serif;font-size:var(--e-global-typography-bccard-font-size);line-height:1.3;font-style:normal;color:var(--e-global-color-primary)}
selector blockquote p{margin:0}
selector img{max-width:100%;height:auto}
@media (prefers-reduced-motion:reduce){selector a{transition:none}}
